import sqlite3

DB_PATH = "billing.db"


def _sum_payments(conn, invoice_id):
    row = conn.execute(
        "SELECT COALESCE(SUM(amount_cents), 0) FROM payments WHERE invoice_id = ?",
        (invoice_id,),
    ).fetchone()
    return row[0]


def get_invoice_balance_summary(invoice_id):
    conn = sqlite3.connect(DB_PATH)
    try:
        total = conn.execute(
            "SELECT total_cents FROM invoices WHERE id = ?", (invoice_id,)
        ).fetchone()[0]
        paid = _sum_payments(conn, invoice_id)
    finally:
        conn.close()
    return {"invoice_id": invoice_id, "total_cents": total, "paid_cents": paid, "balance_cents": total - paid}
